// Format messages for AI context
const messages = $input.first().json.messages || [];
const conversationHistory = messages.map(msg => {
  return `${msg.is_user ? 'User' : 'Assistant'}: ${msg.content}`;
}).join('\n\n');

const newMessage = $input.first().json.newMessage;
const conversationId = $input.first().json.conversationId;

return {
  conversationId,
  conversationHistory,
  newMessage,
  fullContext: `Previous conversation:\n${conversationHistory}\n\nNew message: ${newMessage}`
};
